/* Timed, browser-local interview practice. The public judge uses visible client tests. */
const interviewKey="dv-interview.v1",interviewHistoryKey="dv-interview-history.v1";
const coinSpentKey="dv-coins-spent.v1";
const coinSpent=()=>{const value=Number(localStorage.getItem(coinSpentKey)||0);return Number.isFinite(value)&&value>=0?Math.floor(value):0};
const coinBalance=()=>Math.max(0,5+Object.keys(prog).filter(key=>key.startsWith("c:")&&prog[key]).reduce((sum,key)=>sum+({Easy:10,Medium:20,Hard:30}[CH.find(problem=>problem.i===key.slice(2))?.v]||10),0)+Object.entries(prog).filter(([key,value])=>(key.startsWith("py:")||key.startsWith("sql:"))&&value).reduce((sum,[,value])=>sum+(typeof value==="number"?value:10),0)-coinSpent());
const spendCoins=amount=>{if(coinBalance()<amount)return false;try{localStorage.setItem(coinSpentKey,String(coinSpent()+amount));return true}catch(e){return false}};
const coinLabel=()=>`<span class="dv-wallet" title="Practice coins stay in this browser"><img src="devoal-coin.webp" alt="" width="24" height="24">${coinBalance()} coins</span>`;
const interviewModes={foundation:{name:"Foundation round",minutes:30,levels:["Easy","Medium"]},challenge:{name:"Interview round",minutes:45,levels:["Medium","Hard"]}};
let interviewPatterns=[],interviewHints={},interviewCompanies=[],selectedPattern=null,selectedCompany=null,interviewState=null;
let interviewRunPending=false;
try{const saved=JSON.parse(localStorage.getItem(interviewKey)||"null");if(saved&&interviewModes[saved.mode]&&Array.isArray(saved.questions)&&saved.questions.length===2&&saved.questions.every(id=>typeof id==="string")&&Number.isInteger(saved.current)&&saved.current>=0&&saved.current<2&&Array.isArray(saved.results)&&saved.drafts&&saved.hints&&Number.isFinite(saved.startedAt))interviewState=saved}catch(e){}
const interviewSave=()=>{try{if(interviewState)localStorage.setItem(interviewKey,JSON.stringify(interviewState));else localStorage.removeItem(interviewKey)}catch(e){}};
const interviewHistory=()=>{try{const value=JSON.parse(localStorage.getItem(interviewHistoryKey)||"[]");return Array.isArray(value)?value.filter(run=>run&&Array.isArray(run.questions)&&Array.isArray(run.results)&&Number.isFinite(run.startedAt)):[]}catch(e){return[]}};
const interviewPattern=id=>interviewPatterns.find(pattern=>pattern.problems.includes(id));
const interviewRemaining=()=>interviewState?Math.max(0,interviewState.startedAt+interviewModes[interviewState.mode].minutes*60_000-Date.now()):0;
const interviewTime=ms=>`${String(Math.floor(ms/60_000)).padStart(2,"0")}:${String(Math.floor(ms%60_000/1000)).padStart(2,"0")}`;

async function loadInterviewPatterns(){try{const [patternsResponse,hintsResponse,companiesResponse]=await Promise.all([fetch("interview-patterns.json"),fetch("interview-hints.json"),fetch("interview-companies.json")]);if(!patternsResponse.ok||!hintsResponse.ok||!companiesResponse.ok)throw new Error("Interview guide unavailable");const patterns=await patternsResponse.json(),hints=await hintsResponse.json(),companies=await companiesResponse.json();if(!Array.isArray(patterns)||!hints||typeof hints!=="object"||!Array.isArray(companies))throw new Error("Invalid interview guide");interviewPatterns=patterns;interviewHints=hints;interviewCompanies=companies;if(location.hash==="#interview")renderInterview();if(location.hash==="#plan")renderReadiness()}catch(e){if(location.hash==="#interview")document.getElementById("interview-root").textContent="Interview guide could not load. Refresh and try again.";if(location.hash==="#plan")document.getElementById("readiness-root").textContent="Practice plan could not load. Refresh and try again."}}

function startInterview(mode){if(!interviewModes[mode]||CH.length<20)return;
  const seen=interviewHistory().flatMap(run=>run.questions||[]).reduce((counts,id)=>(counts[id]=(counts[id]||0)+1,counts),{});
  const company=interviewCompanies.find(entry=>entry.id===selectedCompany),pool=company?CH.filter(problem=>company.problems.includes(problem.i)):CH;
  const candidates=pool.filter(problem=>interviewModes[mode].levels.includes(problem.v)).map(problem=>({problem,attempts:seen[problem.i]||0,tie:Math.random()})).sort((a,b)=>a.attempts-b.attempts||a.tie-b.tie);
  if(!interviewModes[mode].levels.every(level=>candidates.some(entry=>entry.problem.v===level)))return;
  const first=candidates.find(entry=>entry.problem.v===interviewModes[mode].levels[0]).problem,firstPattern=interviewPattern(first.i)?.id;
  const second=(candidates.find(entry=>entry.problem.v===interviewModes[mode].levels[1]&&interviewPattern(entry.problem.i)?.id!==firstPattern)||candidates.find(entry=>entry.problem.v===interviewModes[mode].levels[1])).problem;
  interviewState={mode,company:company?.id||null,startedAt:Date.now(),questionStartedAt:Date.now(),questions:[first.i,second.i],current:0,results:[],drafts:{},hints:{},notes:{}};interviewSave();renderInterview()}

function finishInterview(){if(!interviewState)return;const session={...interviewState,finishedAt:Date.now()};const history=interviewHistory();history.unshift(session);try{localStorage.setItem(interviewHistoryKey,JSON.stringify(history.slice(0,30)))}catch(e){}interviewState=null;interviewSave();renderInterview()}

function interviewRecommendation(history){
  const latest=history[0],needsReview=latest?.questions.find(id=>!latest.results.find(row=>row.id===id)?.passed||latest.results.find(row=>row.id===id)?.hintsUsed);
  const next=needsReview||interviewPatterns.flatMap(pattern=>pattern.problems).find(id=>!history.some(run=>run.questions.includes(id)));
  return next?{id:next,pattern:interviewPattern(next)}:null
}

function renderInterview(){const root=document.getElementById("interview-root");if(!root)return;
  if(!interviewPatterns.length||!interviewCompanies.length){root.innerHTML='<p class="why">Loading interview preparation…</p>';return}
  if(interviewState){const state=interviewState,mode=interviewModes[state.mode],remaining=interviewRemaining();if(!remaining){finishInterview();return}
    const problem=CH.find(item=>item.i===state.questions[state.current]);if(!problem){root.textContent="Loading interview problems…";return}const hinted=Math.min(2,Number(state.hints[problem.i])||0),hintLines=interviewHints[problem.i]||["Trace a small example.","Name the invariant before coding."];
    root.innerHTML=`<div class="ip-meta"><span class="mono">${state.company?esc(interviewCompanies.find(entry=>entry.id===state.company)?.name||"")+" · ":""}${mode.name} · Problem ${state.current+1} of 2</span><span class="ip-timer" id="ip-timer" role="timer">${interviewTime(remaining)}</span></div><div class="ip-shell"><section class="ip-card"><h3>${esc(problem.n)} <span class="lv">${problem.v}</span></h3><p>${esc(problem.p)}</p><textarea class="ip-editor" id="ip-code" aria-label="Interview solution" spellcheck="false"></textarea><div class="acts"><button class="btn off" id="ip-run">Run browser tests</button><button class="btn" id="ip-submit">Submit answer</button></div><p class="ip-feedback" id="ip-feedback" role="status"></p></section><aside class="ip-card ip-panel"><h3>Interview notes</h3>${coinLabel()}<p>Explain your approach, edge cases, and time complexity before coding. Tests here give practice feedback; they are inspectable in the browser.</p><button class="btn off" id="ip-hint" ${hinted>=2||hinted===1&&coinBalance()<5?"disabled":""}>${hinted===0?"First hint · free":hinted===1?coinBalance()>=5?"Second hint · 5 coins":"Earn 5 coins for the next hint":"Both hints used"}</button><div id="ip-hint-text" class="ip-guide" ${hinted?"":"hidden"}>${hintLines.slice(0,hinted).map((line,index)=>`<p>${index+1}. ${esc(line)}</p>`).join("")}</div><button class="btn off" id="ip-finish">Finish interview</button></aside></div>`;
    state.notes=state.notes||{};const notes=state.notes[problem.i]||{};
    document.getElementById("ip-hint").insertAdjacentHTML("beforebegin",'<div class="ip-reflection"><label for="ip-approach">Approach to explain</label><textarea id="ip-approach" placeholder="Why does this approach work?"></textarea><label for="ip-complexity">Time and space complexity</label><input id="ip-complexity" placeholder="For example: O(n) time, O(n) space"><label for="ip-edge">Edge cases to mention</label><textarea id="ip-edge" placeholder="Empty input, duplicates, limits…"></textarea></div>');
    document.getElementById("ip-code").value=state.drafts[problem.i]??problem.s;for(const field of ["approach","complexity","edge"])document.getElementById("ip-"+field).value=notes[field]||"";const previous=state.results.at(-1);if(previous)root.insertAdjacentHTML("afterbegin",`<details class="ip-submission" open><summary>Previous submission · ${esc(CH.find(item=>item.i===previous.id)?.n||previous.id)}</summary>${runInsightsHtml(previous.id,previous)}</details>`);return}
  const history=interviewHistory(),last=history[0],next=interviewRecommendation(history);
  const summary=last?`<div class="ip-card ip-report"><h3>Last interview</h3><p>${last.results.filter(row=>row.passed).length} of 2 solved · ${interviewTime((last.finishedAt||Date.now())-last.startedAt)} used · ${history.length} round${history.length===1?"":"s"} saved</p><ol>${last.questions.map(id=>{
    const row=last.results.find(result=>result.id===id),problem=CH.find(item=>item.i===id),notes=last.notes?.[id]||{};
    const reflection=[notes.approach&&`<p><b>Approach:</b> ${esc(notes.approach)}</p>`,notes.complexity&&`<p><b>Complexity:</b> ${esc(notes.complexity)}</p>`,notes.edge&&`<p><b>Edge cases:</b> ${esc(notes.edge)}</p>`].filter(Boolean).join("");
    return `<li>${esc(problem?.n||id)} — ${row?(row.passed?"passed":"needs review"):"not submitted"}. ${row?`${row.hintsUsed||0} hints used · ${interviewTime((row.seconds||0)*1000)} elapsed. `:""}${esc(interviewPattern(id)?.title||"Practice fundamentals")} · <a href="#practice" data-practice="${esc(id)}">Practice again</a>${reflection?`<details class="ip-notes"><summary>Your explanation</summary>${reflection}</details>`:""}${row?.benchmark?`<details class="ip-submission"><summary>Submission performance</summary>${runInsightsHtml(id,row)}</details>`:""}</li>`
  }).join("")}</ol>${next?`<p class="ip-next"><b>Review next:</b> ${esc(next.pattern?.title||"Problem solving")} · <a href="#practice" data-practice="${esc(next.id)}">${esc(CH.find(item=>item.i===next.id)?.n||next.id)} →</a></p>`:""}</div>`:"";
  root.innerHTML=`${summary}<div class="ip-modes"><button class="btn" data-mode="foundation">Start foundation · 30 min</button><button class="btn off" data-mode="challenge">Start interview · 45 min</button>${coinLabel()}</div><p class="why mono">Two problems per round. Questions you have attempted less often appear first. Results and drafts stay in this browser. Solve a problem to earn 10, 20, or 30 coins by difficulty.</p><section class="ip-companies"><div class="ip-section-head"><h3>Company prep paths</h3><p>Independent practice themes. Problems are not claimed as verified company interview questions.</p></div><div class="ip-company-grid">${interviewCompanies.map(company=>`<button class="ip-company${selectedCompany===company.id?" on":""}" data-company="${company.id}" aria-pressed="${selectedCompany===company.id}"><img src="company-icons/${company.id}.svg" alt="" loading="lazy"><span><b>${esc(company.name)}</b><small>${esc(company.focus)}</small></span><em>${company.problems.length} problems</em></button>`).join("")}</div>${selectedCompany?`<div class="ip-company-list"><p>${esc(interviewCompanies.find(company=>company.id===selectedCompany)?.name||"")} practice path · choose a problem below or start a timed round above.</p>${(interviewCompanies.find(company=>company.id===selectedCompany)?.problems||[]).map(id=>{const problem=CH.find(item=>item.i===id);return `<a href="#practice" data-practice="${esc(id)}">${esc(problem?.n||id)} <span>${esc(problem?.v||"")}</span></a>`}).join("")}</div>`:""}</section><div class="ip-section-head"><h3>Learn the patterns</h3><p>Recognize the shape of a problem, then practice that technique.</p></div><div class="ip-grid">${interviewPatterns.map(pattern=>`<section class="ip-card"><h3>${esc(pattern.title)}</h3><p><b>Recognize:</b> ${esc(pattern.recognize)}</p><p><b>Approach:</b> ${esc(pattern.approach)}</p><small>${pattern.problems.length} practice problems</small><div><button class="btn off" data-pattern="${pattern.id}">${selectedPattern===pattern.id?"Hide guide":"Study pattern"}</button></div>${selectedPattern===pattern.id?`<div class="ip-guide">${pattern.problems.map(id=>`<p><a href="#practice" data-practice="${id}">${esc(CH.find(item=>item.i===id)?.n||id)} →</a></p>`).join("")}</div>`:""}</section>`).join("")}</div>`}

document.getElementById("interview-root").addEventListener("input",event=>{if(!interviewState)return;const id=interviewState.questions[interviewState.current];if(event.target.id==="ip-code")interviewState.drafts[id]=event.target.value;else if(["ip-approach","ip-complexity","ip-edge"].includes(event.target.id)){interviewState.notes=interviewState.notes||{};interviewState.notes[id]=interviewState.notes[id]||{};interviewState.notes[id][event.target.id.slice(3)]=event.target.value}else return;interviewSave()});
document.getElementById("interview-root").addEventListener("keydown",event=>{if(event.target.id!=="ip-code")return;if(event.key==="Tab"){event.preventDefault();const input=event.target,pos=input.selectionStart;input.value=input.value.slice(0,pos)+"  "+input.value.slice(input.selectionEnd);input.selectionStart=input.selectionEnd=pos+2;input.dispatchEvent(new Event("input",{bubbles:true}))}if((event.ctrlKey||event.metaKey)&&event.key==="Enter"){event.preventDefault();document.getElementById("ip-run")?.click()}});
document.getElementById("interview-root").addEventListener("click",async event=>{const target=event.target.closest("button,a");if(!target)return;
  if(target.dataset.mode){startInterview(target.dataset.mode);return}
  if(target.dataset.company){selectedCompany=selectedCompany===target.dataset.company?null:target.dataset.company;renderInterview();return}
  if(target.dataset.pattern){selectedPattern=selectedPattern===target.dataset.pattern?null:target.dataset.pattern;renderInterview();return}
  if(target.dataset.practice){const problem=CH.find(item=>item.i===target.dataset.practice);if(problem){pc=problem;practiceFilter.level="All";practiceFilter.query="";practiceFilter.saved=false;location.hash="practice"}return}
  if(!interviewState)return;
  if(target.id==="ip-finish"){finishInterview();return}
  const id=interviewState.questions[interviewState.current],problem=CH.find(item=>item.i===id);
  if(target.id==="ip-hint"){const used=Number(interviewState.hints[id])||0;if(used>=2||used===1&&!spendCoins(5))return;interviewState.hints[id]=used+1;interviewSave();renderInterview();return}
  if(target.id!=="ip-run"&&target.id!=="ip-submit"||interviewRunPending)return;
  const code=document.getElementById("ip-code").value,feedback=document.getElementById("ip-feedback");interviewState.drafts[id]=code;interviewSave();target.disabled=true;feedback.textContent="Running tests…";
  const activeState=interviewState;interviewRunPending=true;const buttons=[document.getElementById("ip-run"),document.getElementById("ip-submit")];buttons.forEach(button=>button.disabled=true);
  let outcome;try{outcome=await runTests(problem,code)}finally{interviewRunPending=false;buttons.forEach(button=>button.disabled=false)}
  if(interviewState!==activeState||interviewState.questions[interviewState.current]!==id||!feedback.isConnected||document.body.dataset.v!=="interview")return;
  document.getElementById("ip-performance")?.remove();const performance=document.createElement("div");performance.id="ip-performance";
  performance.innerHTML=runInsightsHtml(id,{runtimeMs:outcome.runtimeMs,passed:!outcome.err&&outcome.rows.every(row=>row.ok),testsPassed:outcome.rows?.filter(row=>row.ok).length||0,testsTotal:problem.k.length,benchmark:"browser-v1"});feedback.after(performance);
  if(outcome.err){feedback.className="ip-feedback no";feedback.textContent=outcome.err;return}
  const passed=outcome.rows.filter(row=>row.ok).length,total=outcome.rows.length;feedback.className="ip-feedback "+(passed===total?"ok":"no");feedback.textContent=`${passed} of ${total} browser tests passed.`;
  if(target.id==="ip-run")return;
  const elapsedSec=Math.floor((Date.now()-(interviewState.questionStartedAt||interviewState.startedAt))/1000);
  const attempt=recordAttempt(id,passed===total,"interview",passed,total,Number(interviewState.hints[id])||0,elapsedSec,outcome.runtimeMs);
  interviewState.results.push({id,passed:passed===total,testsPassed:passed,testsTotal:total,hintsUsed:Number(interviewState.hints[id])||0,seconds:elapsedSec,runtimeMs:outcome.runtimeMs,benchmark:"browser-v1",at:attempt?.at});
  if(passed===total&&!prog["c:"+id]){prog["c:"+id]=true;bump();save()}
  interviewState.current++;interviewState.questionStartedAt=Date.now();interviewSave();if(interviewState.current>=2)finishInterview();else renderInterview()
});
setInterval(()=>{if(location.hash!=="#interview"||!interviewState)return;const remaining=interviewRemaining(),timer=document.getElementById("ip-timer");if(timer){timer.textContent=interviewTime(remaining);timer.classList.toggle("warn",remaining<300_000)}if(!remaining)finishInterview()},1000);
